def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value.strip()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)

        value = value.strip().lower()
        if value.count("@") != 1:
            return ""

        local, domain = value.split("@")
        if domain in {"gmail.com", "googlemail.com"}:
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"
            value = f"{local}@{domain}"

        return value if valid_email(value) else ""

    def valid_email(value):
        if value.count("@") != 1:
            return False
        local, domain = value.split("@")
        return bool(local) and "." in domain and not domain.startswith(".") and not domain.endswith(".")

    def normalize_phone(value):
        value = re.split(r"x|ext|#", value, maxsplit=1, flags=re.IGNORECASE)[0]
        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        return digits if len(digits) == 10 and digits[0] not in "01" else ""

    def normalize_zip(value):
        value = value.strip()
        if "-" in value:
            value = value.split("-", 1)[0]
        if len(value) == 4 and value.isdigit():
            value = "0" + value
        return value if len(value) == 5 and value.isdigit() else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        if "T" in value:
            return datetime.strptime(value, "%Y-%m-%dT%H:%M:%S")
        if "/" in value:
            return datetime.strptime(value, "%m/%d/%Y")
        return datetime.strptime(value, "%Y-%m-%d")

    def opted_out(value):
        return value.strip().lower() in {"y", "yes", "true", "1"}

    def source_value(value):
        return value.strip().lower()

    people = []
    parent = []

    def find(index):
        while parent[index] != index:
            parent[index] = parent[parent[index]]
            index = parent[index]
        return index

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    records = []
    for row_index, row in enumerate(rows):
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])
        if not email and not phone:
            continue

        records.append({
            "index": row_index,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row["zip"]),
            "source": source_value(row["source"]),
            "updated_dt": parse_updated(row["updated"]),
            "opted_out": opted_out(row["opted_out"]),
            "tags": [
                tag.strip().lower()
                for tag in re.split(r"[;,]", row["tags"])
                if tag.strip()
            ],
        })

    parent = list(range(len(records)))
    email_owner = {}
    phone_last_owner = {}

    for i, record in enumerate(records):
        email = record["email"]
        if email:
            if email in email_owner:
                union(i, email_owner[email])
            else:
                email_owner[email] = i

        phone = record["phone"]
        last_name = record["last_name"].lower()
        if phone and last_name:
            key = (phone, last_name)
            if key in phone_last_owner:
                union(i, phone_last_owner[key])
            else:
                phone_last_owner[key] = i

    groups = {}
    for i, record in enumerate(records):
        groups.setdefault(find(i), []).append(record)

    def choose(group, field, require_valid=False):
        candidates = [
            record for record in group
            if record[field] and (not require_valid or record[field])
        ]
        if not candidates:
            return ""
        winner = min(
            candidates,
            key=lambda record: (
                record["source"] != "manual",
                -record["updated_dt"].timestamp(),
                record["index"],
            ),
        )
        return winner[field]

    output = []
    ordered_groups = sorted(groups.values(), key=lambda group: min(r["index"] for r in group))

    for group in ordered_groups:
        latest = max(record["updated_dt"] for record in group)
        tags = sorted({tag for record in group for tag in record["tags"]})

        output.append({
            "first_name": choose(group, "first_name"),
            "last_name": choose(group, "last_name"),
            "zip": choose(group, "zip"),
            "email": choose(group, "email", require_valid=True),
            "phone": choose(group, "phone", require_valid=True),
            "source": choose(group, "source"),
            "tags": ";".join(tags),
            "opted_out": "Y" if any(record["opted_out"] for record in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })

    return output
